import Foundation

/// 국어 개념 사전 (초등 → 대학교)
extension DoitCurriculum {
    static let korean: [CurriculumEntry] = [
        // MARK: - 초등

        ce(.elementary, "낱말의 짜임", ["낱말", "단어"], "낱말은 뜻을 가지고 홀로 쓰일 수 있는 말의 가장 작은 단위예요. 문장은 여러 낱말이 모여서 만들어져요. 국어사전에서는 낱말을 ㄱ, ㄴ, ㄷ… 차례로 찾아요.\n예: '나는 사과를 먹었다'에는 '나', '는', '사과', '를', '먹었다'라는 낱말이 있어요."),
        ce(.elementary, "낱말의 짜임", ["단일어", "나눌 수 없는 낱말"], "단일어는 더 작은 뜻 있는 낱말로 나눌 수 없는 하나의 낱말이에요. 억지로 나누면 원래 뜻이 없어져요.\n예: 하늘, 바다, 나무, 사람, 먹다"),
        ce(.elementary, "낱말의 짜임", ["복합어", "합친 낱말"], "복합어는 둘 이상의 뜻 있는 부분이 합쳐져 만들어진 낱말이에요. 낱말과 낱말이 합쳐지기도 하고, 뜻을 더해 주는 말이 붙기도 해요.\n예: 밤 + 나무 → 밤나무, 손 + 수건 → 손수건, 풋- + 사과 → 풋사과"),
        ce(.elementary, "낱말의 짜임", ["흉내 내는 말", "의성어와 의태어", "의성어", "의태어"], "흉내 내는 말에는 소리를 흉내 낸 말(의성어)과 모양이나 움직임을 흉내 낸 말(의태어)이 있어요. 글에 쓰면 장면이 생생하게 느껴져요.\n예: 의성어 – 멍멍, 졸졸, 쾅쾅 / 의태어 – 깡충깡충, 반짝반짝, 엉금엉금"),
        ce(.elementary, "낱말의 짜임", ["비슷한말", "유의어"], "비슷한말은 소리는 다르지만 뜻이 서로 비슷한 낱말이에요. 뜻이 완전히 같지는 않아서 상황에 맞게 골라 써야 해요.\n예: 기쁘다 – 즐겁다, 말 – 언어, 가끔 – 때때로"),
        ce(.elementary, "낱말의 짜임", ["반대말", "반의어", "뜻이 반대인 낱말"], "반대말은 서로 뜻이 반대되는 낱말이에요. 한 가지 기준에서만 뜻이 반대이고 나머지는 같아요.\n예: 크다 – 작다, 길다 – 짧다, 오다 – 가다, 위 – 아래"),
        ce(.elementary, "낱말의 짜임", ["상위어", "하위어", "포함하는 말"], "다른 낱말들의 뜻을 포함하는 낱말을 상위어, 그 안에 포함되는 낱말을 하위어라고 해요. 상위어는 뜻이 넓고 하위어는 뜻이 좁고 구체적이에요.\n예: '과일'은 상위어, '사과·배·포도'는 하위어예요."),
        ce(.elementary, "낱말의 짜임", ["다의어", "뜻이 여러 개인 낱말"], "다의어는 하나의 낱말이 서로 관련 있는 여러 뜻을 가진 것이에요. 문장 속에서 어떤 뜻으로 쓰였는지 앞뒤를 보고 판단해요.\n예: '손'은 '손을 씻다(신체)', '손이 모자라다(일할 사람)', '손을 끊다(관계)'처럼 여러 뜻으로 쓰여요."),

        ce(.elementary, "문장의 짜임", ["문장"], "문장은 생각이나 느낌을 완결된 형태로 나타낸 말의 단위예요. 글로 쓸 때는 끝에 마침표, 물음표, 느낌표 같은 문장 부호를 찍어요.\n예: 강아지가 뛰어요. / 너는 어디 가니? / 정말 멋지구나!"),
        ce(.elementary, "문장의 짜임", ["문장의 기본 짜임", "누가 어찌하다", "무엇이 어떠하다"], "문장은 기본적으로 '무엇이(누가) + 어찌하다', '무엇이 + 어떠하다', '무엇이 + 무엇이다'의 짜임을 가져요. 여기에 '무엇을' 같은 말이 더해지기도 해요.\n예: 새가 난다(어찌하다) / 꽃이 예쁘다(어떠하다) / 나는 학생이다(무엇이다)"),
        ce(.elementary, "문장의 짜임", ["꾸며 주는 말", "수식하는 말"], "꾸며 주는 말은 다른 말 앞에서 그 뜻을 더 자세하고 분명하게 해 주는 말이에요. 꾸며 주는 말을 넣으면 문장이 더 생생해져요.\n예: '꽃이 피었다' → '빨간 꽃이 활짝 피었다'에서 '빨간', '활짝'이 꾸며 주는 말이에요."),
        ce(.elementary, "문장의 짜임", ["이어 주는 말", "접속어", "접속하는 말"], "이어 주는 말은 문장과 문장을 자연스럽게 이어 주는 말이에요. 앞뒤 문장의 관계에 따라 알맞은 말을 골라 써요.\n예: 그리고(나열), 그러나·하지만(반대), 그래서(원인과 결과), 왜냐하면(이유)"),
        ce(.elementary, "문장의 짜임", ["시간 표현", "때를 나타내는 말"], "문장에는 일이 일어난 때를 나타내는 표현이 있어요. '어제·지금·내일' 같은 낱말과 문장 끝의 모양이 서로 어울려야 해요.\n예: 어제 비가 왔다(지난 일) / 지금 비가 온다(지금 일) / 내일 비가 올 것이다(앞으로 일)"),
        ce(.elementary, "문장의 짜임", ["문장 부호", "마침표", "쉼표", "따옴표"], "문장 부호는 문장의 뜻을 정확하게 전하려고 쓰는 부호예요. 마침표(.)는 설명하는 문장 끝, 물음표(?)는 묻는 문장 끝, 느낌표(!)는 느낌을 나타낼 때, 쉼표(,)는 쉬거나 나열할 때 써요. 큰따옴표(“ ”)는 직접 한 말, 작은따옴표(‘ ’)는 마음속으로 한 말에 써요.\n예: 엄마가 “밥 먹자.” 하고 부르셨다."),

        ce(.elementary, "높임 표현", ["높임 표현", "높임법", "높임말"], "높임 표현은 말하는 사람이 웃어른이나 듣는 사람을 높여서 예의를 나타내는 표현이에요. 높임을 나타내는 낱말, '께서·께', 문장 속 '-시-', '-요·-습니다' 같은 문장 끝을 써서 높여요.\n예: 할아버지께서 진지를 잡수신다. / 선생님, 안녕하세요?"),
        ce(.elementary, "높임 표현", ["높임 어휘", "높임을 나타내는 낱말"], "높임 어휘는 그 자체로 높이는 뜻을 가진 낱말이에요. 웃어른과 관련된 말에는 보통 낱말 대신 높임 어휘를 써요.\n예: 밥 → 진지, 집 → 댁, 나이 → 연세, 자다 → 주무시다, 주다 → 드리다, 묻다 → 여쭙다"),
        ce(.elementary, "높임 표현", ["높임 조사", "께서", "께"], "높임 조사는 높여야 할 사람 뒤에 붙는 조사예요. '이/가' 대신 '께서'를, '에게' 대신 '께'를 써요.\n예: 어머니가 오셨다 → 어머니께서 오셨다 / 선생님에게 드렸다 → 선생님께 드렸다"),
        ce(.elementary, "높임 표현", ["잘못된 높임 표현", "사물 높임"], "높여야 할 사람이 아니라 물건을 높이는 것은 잘못된 높임 표현이에요. 또 웃어른 앞에서 자기를 높이는 말을 쓰는 것도 어색해요.\n예: '주문하신 커피 나오셨습니다'(×) → '주문하신 커피 나왔습니다'(○)"),

        ce(.elementary, "글의 종류", ["설명하는 글", "설명문"], "설명하는 글은 어떤 대상에 대한 지식이나 정보를 읽는 사람이 이해하기 쉽게 풀어 쓴 글이에요. 사실을 바탕으로 정확하고 객관적으로 써야 해요. 보통 처음(대상 소개) – 가운데(자세한 설명) – 끝(정리)으로 짜여요.\n예: '우리나라의 전통 악기', '꿀벌의 한살이'"),
        ce(.elementary, "글의 종류", ["주장하는 글", "논설문"], "주장하는 글은 어떤 문제에 대한 자신의 생각(주장)을 내세우고, 알맞은 까닭(근거)을 들어 읽는 사람을 설득하는 글이에요. 서론 – 본론 – 결론으로 짜이고, 근거는 주장과 관련 있고 믿을 만해야 해요.\n예: '교실에서 바른 말을 쓰자', '일회용품 사용을 줄이자'"),
        ce(.elementary, "글의 종류", ["편지글", "편지"], "편지글은 특정한 사람에게 자기의 소식이나 마음을 전하는 글이에요. 받을 사람, 첫인사, 전하고 싶은 말, 끝인사, 쓴 날짜, 쓴 사람의 순서로 써요.\n예: 사랑하는 할머니께 / 할머니, 그동안 잘 지내셨어요? … / 20○○년 5월 8일 / 손녀 지민 올림"),
        ce(.elementary, "글의 종류", ["기행문", "여행 글"], "기행문은 여행하면서 보고, 듣고, 느낀 것을 쓴 글이에요. 여정(다닌 곳), 견문(보고 들은 것), 감상(생각이나 느낌)이 들어가요.\n예: '경주에 가서 불국사를 보았다(여정·견문). 천 년 넘게 남아 있다니 놀라웠다(감상).'"),
        ce(.elementary, "글의 종류", ["독서 감상문", "독후감"], "독서 감상문은 책을 읽고 생각하거나 느낀 점을 쓴 글이에요. 책을 읽게 된 까닭, 책 내용, 인상 깊은 부분과 그 까닭, 생각이나 느낌을 담아요. 편지, 일기, 시처럼 다양한 형식으로 쓸 수도 있어요.\n예: '흥부전'을 읽고 흥부에게 편지 쓰기"),
        ce(.elementary, "글의 종류", ["전기문", "위인전"], "전기문은 실제로 살았던 인물의 생애와 업적을 사실에 바탕을 두고 쓴 글이에요. 인물, 사건, 배경, 글쓴이의 생각(평가)이 담겨 있어요. 인물이 살았던 시대 상황과 가치관을 함께 생각하며 읽으면 좋아요.\n예: 세종 대왕, 이순신, 유관순의 삶을 다룬 글"),
        ce(.elementary, "글의 종류", ["기사문", "육하원칙", "뉴스 기사"], "기사문은 일어난 일을 사실대로 알리는 글이에요. 누가, 언제, 어디서, 무엇을, 어떻게, 왜의 육하원칙에 따라 쓰고 표제, 부제, 전문, 본문으로 짜여요.\n예: '○○초등학교 학생들이(누가) 지난 5일(언제) 학교 강당에서(어디서) 환경 캠페인을(무엇을) 열었다.'"),

        ce(.elementary, "시 감상", ["시", "동시"], "시는 생각이나 느낌을 짧고 리듬감 있는 말로 표현한 글이에요. 같은 말이나 비슷한 짜임을 반복해 말의 재미와 리듬을 살리기도 해요. 어린이의 마음을 담아 쓴 시를 동시라고 해요.\n예: '퐁당퐁당 돌을 던지자'처럼 같은 말을 되풀이하면 노래하듯 읽혀요."),
        ce(.elementary, "시 감상", ["행과 연", "행", "연"], "시에서 한 줄 한 줄을 행이라고 하고, 몇 개의 행이 모여 한 덩어리를 이룬 것을 연이라고 해요. 연과 연 사이는 한 줄을 띄어서 구분해요.\n예: 4개의 행이 모인 덩어리가 3개 있으면 '3연 12행의 시'라고 해요."),
        ce(.elementary, "시 감상", ["말하는 이", "시 속의 말하는 이"], "시 속에서 생각이나 느낌을 말하는 사람을 '말하는 이'라고 해요. 시를 쓴 사람과 같을 수도 있고 다를 수도 있어요. 말하는 이가 처한 상황과 마음을 짐작하며 읽으면 시를 더 깊이 이해할 수 있어요.\n예: 아이가 엄마를 기다리는 시에서 말하는 이는 '기다리는 아이'예요."),
        ce(.elementary, "시 감상", ["감각적 표현", "감각을 살린 표현"], "감각적 표현은 눈, 귀, 코, 혀, 피부로 느끼는 것처럼 생생하게 나타낸 표현이에요. 읽는 사람이 장면을 머릿속에 그릴 수 있어요.\n예: 노란 개나리(보는 느낌), 졸졸 흐르는 시냇물(듣는 느낌), 달콤한 딸기(맛보는 느낌)"),
        ce(.elementary, "시 감상", ["비유하는 표현", "비유 표현"], "비유하는 표현은 나타내려는 대상을 비슷한 점이 있는 다른 대상에 빗대어 표현하는 방법이에요. '처럼', '같이' 같은 말을 쓰기도 하고 바로 '~은 ~이다'라고 하기도 해요.\n예: 솜사탕 같은 구름 / 내 동생은 귀여운 다람쥐예요."),

        ce(.elementary, "이야기 감상", ["이야기의 구성 요소", "인물 사건 배경"], "이야기는 인물, 사건, 배경으로 이루어져 있어요. 인물은 이야기에 나오는 사람이나 동물, 사건은 인물이 겪는 일, 배경은 일이 일어난 때와 곳이에요.\n예: '흥부와 놀부' – 인물: 흥부, 놀부 / 사건: 제비 다리를 고쳐 줌 / 배경: 옛날 어느 마을"),
        ce(.elementary, "이야기 감상", ["인물의 성격", "인물의 마음"], "인물의 성격은 인물이 하는 말과 행동, 표정을 보고 짐작할 수 있어요. 인물이 왜 그렇게 행동했는지 생각하면 이야기를 더 깊이 이해할 수 있어요.\n예: 다친 제비를 정성껏 돌본 흥부의 행동에서 착하고 마음이 따뜻한 성격을 알 수 있어요."),
        ce(.elementary, "이야기 감상", ["이야기의 배경", "시간적 배경", "공간적 배경"], "배경은 이야기 속 사건이 일어나는 때(시간적 배경)와 곳(공간적 배경)이에요. 배경은 이야기의 분위기를 만들고 인물의 행동에도 영향을 줘요.\n예: '깊은 밤, 아무도 없는 숲속'이라는 배경은 무섭고 긴장된 분위기를 만들어요."),
        ce(.elementary, "이야기 감상", ["이야기의 흐름", "처음 가운데 끝"], "이야기는 사건이 일어난 차례에 따라 흘러가요. 처음에는 인물과 배경이 소개되고, 가운데에서 사건이 일어나 커지며, 끝에서 사건이 해결돼요. 흐름을 정리하면 이야기를 간추리기 쉬워요.\n예: 처음 – 토끼와 거북이 경주를 함 / 가운데 – 토끼가 낮잠을 잠 / 끝 – 거북이 이김"),
        ce(.elementary, "이야기 감상", ["극본", "해설 지문 대사"], "극본은 연극을 하려고 쓴 글이에요. 해설(때·곳·등장인물 소개), 지문(인물의 행동·표정·무대 설명), 대사(인물이 하는 말)로 이루어져요.\n예: 지문 – (문을 열고 들어오며) / 대사 – 흥부: 형님, 쌀 한 됫박만 꾸어 주세요."),

        ce(.elementary, "맞춤법과 띄어쓰기", ["띄어쓰기"], "우리말은 낱말과 낱말 사이를 띄어 써요. 하지만 '은/는, 이/가, 을/를' 같은 조사는 앞말에 붙여 써요. '개, 마리, 권' 같은 단위를 나타내는 말은 앞말과 띄어 쓰지만 숫자와 함께 쓸 때는 붙여 쓸 수 있어요.\n예: 아버지가방에들어가신다 → 아버지가 방에 들어가신다 / 사과 한 개, 사과 3개"),
        ce(.elementary, "맞춤법과 띄어쓰기", ["소리와 표기가 다른 낱말", "소리 나는 대로 쓰지 않는 낱말"], "우리말에는 소리 나는 것과 글자로 쓰는 것이 다른 낱말이 많아요. 받침이 뒤 글자로 넘어가 소리 나거나 소리가 바뀌어도 원래 모양을 밝혀 써요.\n예: [머거요] → 먹어요, [가치] → 같이, [구지] → 굳이, [궁물] → 국물"),
        ce(.elementary, "맞춤법과 띄어쓰기", ["헷갈리는 낱말", "바른 낱말 쓰기"], "소리나 모양이 비슷해서 헷갈리기 쉬운 낱말은 뜻을 구별해서 써야 해요.\n예: 가르치다(지식을 알려 주다) – 가리키다(손가락으로 방향을 알리다) / 잊다(기억하지 못하다) – 잃다(물건을 없어지게 하다) / 맞히다(정답을 맞히다) – 맞추다(퍼즐을 맞추다)"),
        ce(.elementary, "맞춤법과 띄어쓰기", ["겹받침"], "겹받침은 서로 다른 자음 두 개로 이루어진 받침이에요. 뒤에 모음이 오면 두 자음이 모두 소리 나지만, 자음이 오거나 낱말이 끝나면 하나만 소리 나요.\n예: 닭[닥], 닭이[달기] / 앉다[안따], 앉아[안자] / 읽다[익따], 읽어[일거]"),
        ce(.elementary, "맞춤법과 띄어쓰기", ["되와 돼", "되요 돼요"], "'돼'는 '되어'를 줄인 말이에요. 그래서 '되어'로 바꾸어 말이 되면 '돼', 안 되면 '되'를 써요.\n예: 그러면 안 돼(=안 되어). / 선생님이 되고 싶어('되어고'는 어색하니까 '되'를 써요). / '되요'가 아니라 '돼요'가 맞아요."),

        ce(.elementary, "말하기와 듣기", ["토의"], "토의는 여러 사람이 공통의 문제를 해결하려고 서로 의견을 나누며 가장 좋은 방법을 찾는 말하기예요. 의견을 말할 때는 까닭을 함께 말하고, 다른 사람의 의견을 존중해요.\n예: '학급 문고를 잘 관리하려면 어떻게 해야 할까?'를 주제로 의견 나누기"),
        ce(.elementary, "말하기와 듣기", ["토론", "찬반 토론"], "토론은 어떤 주제에 대해 찬성편과 반대편이 근거를 들어 자기 주장이 옳다고 상대를 설득하는 말하기예요. 사회자가 정한 순서와 규칙에 따라 진행하고, 주장 펼치기 – 반론하기 – 주장 다지기 순서로 해요.\n예: 논제 '초등학생의 휴대 전화 사용을 제한해야 한다'"),
        ce(.elementary, "말하기와 듣기", ["회의", "회의 절차"], "회의는 여러 사람이 모여 의논하고 결정하는 일이에요. 보통 개회 – 주제 선정 – 주제 토의 – 표결 – 결과 발표 – 폐회 순서로 진행해요. 사회자, 참여자, 기록자가 각자 역할을 맡아요.\n예: 학급 회의에서 '교실 청소 방법'을 표결로 정하기"),
        ce(.elementary, "말하기와 듣기", ["면담", "인터뷰"], "면담은 알고 싶은 것을 그 분야를 잘 아는 사람을 직접 만나 묻고 답을 듣는 활동이에요. 면담 목적을 정하고, 질문을 미리 준비하고, 예의 바르게 묻고 들은 내용을 기록해요.\n예: 소방관을 만나 '불이 났을 때 가장 먼저 무엇을 해야 하나요?'라고 묻기"),

        ce(.elementary, "읽기 전략", ["문단"], "문단은 하나의 중심 생각을 중심으로 여러 문장이 모인 글의 덩어리예요. 새 문단은 줄을 바꾸고 첫 칸을 들여 써요. 문단은 중심 문장과 이를 도와주는 뒷받침 문장으로 이루어져요.\n예: '봄에는 꽃이 핀다.'(중심 문장) + '개나리, 진달래, 벚꽃이 핀다.'(뒷받침 문장)"),
        ce(.elementary, "읽기 전략", ["중심 문장", "중심 생각", "뒷받침 문장"], "중심 문장은 문단에서 가장 중요한 내용을 담은 문장이에요. 주로 문단의 처음이나 끝에 있고, 나머지 뒷받침 문장들은 중심 문장을 자세히 설명하거나 예를 들어요.\n예: '운동은 몸에 좋다. 심장이 튼튼해지고, 잠도 잘 온다.'에서 중심 문장은 첫 문장이에요."),
        ce(.elementary, "읽기 전략", ["요약하기", "간추리기"], "요약하기는 글의 중요한 내용만 골라 짧게 정리하는 것이에요. 문단마다 중심 문장을 찾고, 반복되거나 덜 중요한 내용은 빼고, 여러 낱말은 상위어로 묶어 정리해요.\n예: '사과, 배, 감을 샀다' → '과일을 샀다'로 간추리기"),
        ce(.elementary, "읽기 전략", ["사실과 의견", "사실", "의견"], "사실은 실제로 있었던 일이나 확인할 수 있는 내용이고, 의견은 어떤 대상에 대한 자기 생각이에요. 글을 읽을 때 둘을 구별하면 내용을 비판적으로 판단할 수 있어요.\n예: '이 공원에는 나무가 100그루 있다.'(사실) / '이 공원은 가장 아름답다.'(의견)"),

        // MARK: - 중학교

        ce(.middle, "품사의 분류", ["품사", "9품사", "품사 분류 기준"], "품사는 단어를 형태, 기능, 의미에 따라 나눈 갈래예요. 국어의 품사는 명사, 대명사, 수사, 조사, 동사, 형용사, 관형사, 부사, 감탄사의 9가지예요. 기능에 따라 묶으면 체언(명사·대명사·수사), 관계언(조사), 용언(동사·형용사), 수식언(관형사·부사), 독립언(감탄사)이 돼요.\n예: '아, 새 책이 정말 좋다.' → 감탄사, 관형사, 명사, 조사, 부사, 형용사"),
        ce(.middle, "품사의 분류", ["명사", "이름씨"], "명사는 사람이나 사물, 장소, 개념 등의 이름을 나타내는 단어예요. 체언에 속하며 조사와 결합해 문장의 주어나 목적어 등으로 쓰여요. 특정한 대상의 이름인 고유 명사와 두루 쓰이는 보통 명사, 홀로 쓰이지 못하는 의존 명사가 있어요.\n예: 서울(고유 명사), 학교(보통 명사), '먹을 것'의 '것'(의존 명사)"),
        ce(.middle, "품사의 분류", ["대명사", "대이름씨"], "대명사는 사람이나 사물, 장소의 이름을 대신 가리키는 단어예요. 사람을 가리키는 인칭 대명사와 사물·장소를 가리키는 지시 대명사가 있어요.\n예: 나, 너, 우리, 그분(인칭 대명사) / 이것, 저것, 여기, 거기(지시 대명사)"),
        ce(.middle, "품사의 분류", ["수사", "셈씨"], "수사는 사물의 수량이나 순서를 나타내는 단어예요. 수량을 나타내는 양수사와 순서를 나타내는 서수사가 있어요. 조사가 붙을 수 있다는 점에서 수 관형사와 구별돼요.\n예: 하나, 둘, 일, 이(양수사) / 첫째, 둘째, 제일(서수사) / '사과 하나를 먹었다'의 '하나'는 수사, '사과 한 개'의 '한'은 관형사예요."),
        ce(.middle, "품사의 분류", ["조사", "토씨"], "조사는 주로 체언 뒤에 붙어 다른 말과의 문법적 관계를 나타내거나 특별한 뜻을 더해 주는 단어예요. 격 조사, 보조사, 접속 조사가 있어요. 조사는 단어지만 앞말에 붙여 써요.\n예: 철수가(격 조사) / 나도, 너만(보조사) / 사과와 배(접속 조사)"),
        ce(.middle, "품사의 분류", ["동사", "움직씨"], "동사는 사람이나 사물의 움직임이나 작용을 나타내는 단어예요. 용언에 속하며 어미가 바뀌는 활용을 해요. 현재를 나타내는 '-는다/-ㄴ다'나 명령형 '-아라/-어라'와 자연스럽게 결합해요.\n예: 먹다 → 먹는다, 먹어라 / 달리다, 읽다, 피다"),
        ce(.middle, "품사의 분류", ["형용사", "그림씨"], "형용사는 사람이나 사물의 성질이나 상태를 나타내는 단어예요. 동사처럼 활용하지만 보통 현재형 '-는다/-ㄴ다', 명령형, 청유형과는 어울리지 않아요.\n예: 예쁘다 → '예쁜다'(×), '예뻐라'(명령 ×) / 크다, 푸르다, 착하다"),
        ce(.middle, "품사의 분류", ["관형사", "매김씨"], "관형사는 체언 앞에서 체언의 뜻을 꾸며 주는 단어예요. 형태가 변하지 않고 조사가 붙지 않아요. 성상 관형사, 지시 관형사, 수 관형사가 있어요.\n예: 새 옷(성상), 이 책(지시), 두 사람(수)"),
        ce(.middle, "품사의 분류", ["부사", "어찌씨"], "부사는 주로 용언 앞에서 그 뜻을 꾸며 주는 단어예요. 다른 부사나 문장 전체를 꾸미기도 하고, 문장을 이어 주는 접속 부사도 있어요. 형태가 변하지 않아요.\n예: 매우 빠르다 / 아주 잘 / 과연 그는 왔다 / 그러나, 그리고(접속 부사)"),
        ce(.middle, "품사의 분류", ["감탄사", "느낌씨"], "감탄사는 말하는 이의 느낌이나 놀람, 부름, 대답을 나타내는 단어예요. 문장의 다른 성분과 직접 관계를 맺지 않고 독립적으로 쓰이며, 위치가 비교적 자유로워요.\n예: 아, 어머나, 이봐, 네, 아니요"),
        ce(.middle, "품사의 분류", ["용언의 활용", "활용", "어간과 어미"], "동사와 형용사는 쓰임에 따라 모양이 바뀌는데, 이를 활용이라고 해요. 활용할 때 변하지 않는 부분을 어간, 변하는 부분을 어미라고 해요. 기본형은 어간에 '-다'를 붙인 형태예요.\n예: 먹다 → 먹고, 먹으니, 먹어서 (어간 '먹-', 어미 '-고, -으니, -어서')"),

        ce(.middle, "문장 성분", ["문장 성분", "주성분", "부속 성분", "독립 성분"], "문장 성분은 문장 안에서 어떤 역할을 하는지에 따라 나눈 문장의 구성 요소예요. 주성분(주어, 서술어, 목적어, 보어), 부속 성분(관형어, 부사어), 독립 성분(독립어)이 있어요. 품사는 단어 자체의 성질이고, 문장 성분은 문장 속 역할이라는 점이 달라요.\n예: '아, 귀여운 강아지가 빨리 뛴다.' → 독립어, 관형어, 주어, 부사어, 서술어"),
        ce(.middle, "문장 성분", ["주어"], "주어는 문장에서 동작이나 상태, 성질의 주체가 되는 성분이에요. '누가', '무엇이'에 해당하고, 주로 체언에 주격 조사 '이/가, 께서'가 붙어서 만들어져요. 보조사가 붙거나 조사가 생략되기도 해요.\n예: 꽃이 핀다. / 할머니께서 웃으신다. / 나는 학생이다."),
        ce(.middle, "문장 성분", ["서술어"], "서술어는 주어의 동작, 상태, 성질 등을 풀이하는 성분이에요. '어찌하다, 어떠하다, 무엇이다'에 해당하며 주로 동사, 형용사, '체언 + 이다'로 이루어져요. 서술어에 따라 꼭 필요한 성분의 수(서술어의 자릿수)가 정해져요.\n예: 새가 난다(한 자리) / 나는 책을 읽는다(두 자리) / 형이 나에게 선물을 주었다(세 자리)"),
        ce(.middle, "문장 성분", ["목적어"], "목적어는 서술어가 나타내는 동작의 대상이 되는 성분이에요. '무엇을', '누구를'에 해당하며 주로 체언에 목적격 조사 '을/를'이 붙어 만들어져요.\n예: 나는 사과를 먹었다. / 친구를 만났다."),
        ce(.middle, "문장 성분", ["보어"], "보어는 서술어 '되다', '아니다' 앞에서 문장을 완전하게 해 주는 성분이에요. 체언에 보격 조사 '이/가'가 붙어서 만들어져요. '되다·아니다' 앞의 '이/가'만 보어이고, 다른 서술어 앞은 주어예요.\n예: 물이 얼음이 되었다. / 그는 학생이 아니다. ('얼음이', '학생이'가 보어)"),
        ce(.middle, "문장 성분", ["관형어"], "관형어는 체언 앞에서 체언을 꾸며 주는 부속 성분이에요. 관형사, 체언 + 관형격 조사 '의', 용언의 관형사형('-ㄴ, -는, -ㄹ')으로 만들어져요.\n예: 새 신발(관형사) / 나의 꿈(체언 + 의) / 예쁜 꽃(용언의 관형사형)"),
        ce(.middle, "문장 성분", ["부사어"], "부사어는 주로 서술어를 꾸며 그 뜻을 자세하게 해 주는 부속 성분이에요. 부사, 체언 + 부사격 조사('에, 에서, 으로' 등), 용언의 부사형('-게')으로 만들어져요. 대부분 생략할 수 있지만, '닮다·주다' 같은 서술어가 꼭 필요로 하는 필수적 부사어도 있어요.\n예: 매우 춥다 / 학교에서 공부한다 / 아이가 엄마와 닮았다(필수적 부사어)"),
        ce(.middle, "문장 성분", ["독립어"], "독립어는 문장의 다른 성분과 직접적인 관계없이 따로 떨어져 쓰이는 성분이에요. 감탄사나 '체언 + 호격 조사(아/야)'로 이루어져요.\n예: 와, 눈이 온다! / 민수야, 밥 먹자. / 네, 알겠습니다."),

        ce(.middle, "음운의 체계", ["음운"], "음운은 말의 뜻을 구별해 주는 소리의 가장 작은 단위예요. 자음과 모음 같은 분절 음운과, 소리의 길이·높낮이처럼 뜻을 구별해 주는 비분절 음운이 있어요.\n예: '불'과 '풀'은 ㅂ과 ㅍ 하나 때문에 뜻이 달라져요. / 말[馬]과 말ː[言]은 소리의 길이로 구별돼요."),
        ce(.middle, "음운의 체계", ["자음 체계", "자음", "조음 위치", "조음 방법"], "자음은 공기가 입안에서 장애를 받으며 나는 소리로, 국어에는 19개가 있어요. 소리 나는 위치(입술소리, 잇몸소리, 센입천장소리, 여린입천장소리, 목청소리)와 소리 내는 방법(파열음, 마찰음, 파찰음, 비음, 유음)에 따라 나눠요. 파열음·파찰음은 다시 예사소리, 된소리, 거센소리로 나뉘어요.\n예: ㅂ·ㅃ·ㅍ·ㅁ은 입술소리, ㄱ·ㄲ·ㅋ·ㅇ은 여린입천장소리"),
        ce(.middle, "음운의 체계", ["단모음 체계", "단모음", "모음 체계"], "단모음은 발음하는 동안 입술 모양이나 혀의 위치가 바뀌지 않는 모음으로, 표준 발음법에서는 ㅏ, ㅐ, ㅓ, ㅔ, ㅗ, ㅚ, ㅜ, ㅟ, ㅡ, ㅣ의 10개예요. 혀의 최고점 위치(전설·후설), 혀의 높이(고·중·저모음), 입술 모양(평순·원순)에 따라 나눠요. ㅚ와 ㅟ는 이중 모음으로 발음하는 것도 허용돼요.\n예: ㅣ는 전설·고모음·평순 모음, ㅜ는 후설·고모음·원순 모음이에요."),
        ce(.middle, "음운의 체계", ["이중 모음", "이중모음", "반모음"], "이중 모음은 발음하는 동안 입술 모양이나 혀의 위치가 바뀌는 모음이에요. 반모음과 단모음이 결합해 만들어지며, 국어에는 ㅑ, ㅒ, ㅕ, ㅖ, ㅘ, ㅙ, ㅛ, ㅝ, ㅞ, ㅠ, ㅢ의 11개가 있어요.\n예: ㅑ = 반모음 [j] + ㅏ, ㅘ = 반모음 [w] + ㅏ"),
        ce(.middle, "음운의 체계", ["음절", "소리마디"], "음절은 한 번에 소리 낼 수 있는 소리의 덩어리예요. 국어의 음절에는 반드시 모음이 하나 있어야 하고, 첫소리와 끝소리에는 자음이 하나씩만 올 수 있어요. 그래서 음절의 유형은 모음, 자음+모음, 모음+자음, 자음+모음+자음의 네 가지예요.\n예: 아(모음), 가(자음+모음), 안(모음+자음), 강(자음+모음+자음)"),

        ce(.middle, "어휘의 체계와 양상", ["고유어", "토박이말"], "고유어는 우리말에 본디부터 있던 말이나 그것을 바탕으로 새로 만든 말이에요. 정서적이고 친근한 느낌을 주며, 감각어와 흉내 내는 말이 발달해 있어요.\n예: 하늘, 아버지, 노랗다, 노르스름하다, 샛노랗다"),
        ce(.middle, "어휘의 체계와 양상", ["한자어"], "한자어는 한자를 바탕으로 만들어진 말로, 국어 어휘에서 큰 비중을 차지해요. 고유어보다 뜻이 세분되어 있고, 전문적이고 격식 있는 느낌을 주는 경우가 많아요. 고유어 하나에 여러 한자어가 대응하기도 해요.\n예: '생각' – 사고(思考), 의견(意見), 고려(考慮)"),
        ce(.middle, "어휘의 체계와 양상", ["외래어", "외국어와 외래어"], "외래어는 외국에서 들어온 말 가운데 국어처럼 널리 쓰이는 말이에요. 우리말로 바꾸기 어려운 것도 있지만, 알맞은 우리말이 있으면 우리말을 쓰는 것이 좋아요. 외래어는 '외래어 표기법'에 따라 적어요.\n예: 버스, 컴퓨터, 라디오, 피아노"),
        ce(.middle, "어휘의 체계와 양상", ["방언", "지역 방언", "사회 방언"], "방언은 지역이나 사회 집단에 따라 다르게 쓰이는 말이에요. 지역에 따라 달라지는 지역 방언(사투리)과 세대, 성별, 직업 등에 따라 달라지는 사회 방언이 있어요. 방언은 그 지역의 문화와 정서를 담고 있어 소중한 자산이에요.\n예: '부추'를 '정구지(경상)', '솔(전라)'이라고 함 / 의사들끼리 쓰는 전문어"),

        ce(.middle, "시의 운율과 심상", ["시적 화자", "화자", "서정적 자아"], "시적 화자는 시 속에서 말하는 사람으로, 시인이 만들어 낸 목소리예요. 시인과 같을 수도 있지만 어린아이, 여성, 사물 등 다른 존재가 화자가 되기도 해요. 화자의 처지와 정서, 태도를 파악하는 것이 시 감상의 출발이에요.\n예: 김소월 '진달래꽃'의 화자는 떠나는 임을 보내는 여인이에요."),
        ce(.middle, "시의 운율과 심상", ["운율", "리듬", "음보율", "음수율"], "운율은 시에서 느껴지는 말의 가락이에요. 같은 소리나 단어, 구절, 문장 구조를 반복하거나, 글자 수(음수율)나 끊어 읽는 마디 수(음보율)를 일정하게 해서 만들어요. 일정한 규칙 없이 시 안에서 자연스럽게 느껴지는 내재율도 있어요.\n예: '나 보기가 / 역겨워 / 가실 때에는'처럼 세 마디로 끊어 읽히는 3음보"),
        ce(.middle, "시의 운율과 심상", ["심상", "이미지", "공감각적 심상"], "심상은 시를 읽을 때 마음속에 떠오르는 감각적인 모습이나 느낌이에요. 시각, 청각, 후각, 미각, 촉각적 심상이 있고, 한 감각을 다른 감각으로 옮겨 표현한 것을 공감각적 심상이라고 해요.\n예: '금빛 게으른 울음'(정지용 '향수') – 청각인 울음을 시각인 금빛으로 표현한 공감각적 심상"),

        ce(.middle, "비유와 상징", ["직유법"], "직유법은 '~처럼, ~같이, ~듯이' 같은 연결어를 써서 원관념과 보조 관념을 직접 연결하는 비유법이에요. 두 대상의 비슷한 점이 겉으로 분명하게 드러나요.\n예: 앵두 같은 입술 / 쟁반같이 둥근 달"),
        ce(.middle, "비유와 상징", ["은유법"], "은유법은 연결어 없이 'A는 B이다'처럼 원관념을 보조 관념에 바로 빗대는 비유법이에요. 직유보다 함축적이고 강한 인상을 줘요.\n예: 내 마음은 호수요. (김동명 '내 마음은') / 시간은 금이다."),
        ce(.middle, "비유와 상징", ["의인법", "활유법"], "의인법은 사람이 아닌 대상을 사람처럼 생각하고 행동하는 것으로 표현하는 비유법이에요. 생명이 없는 것을 살아 있는 생물처럼 표현하는 것은 활유법이라고 해요.\n예: 꽃들이 방긋 웃는다. (의인법) / 울부짖는 바다 (활유법)"),
        ce(.middle, "비유와 상징", ["상징", "원관념과 보조 관념"], "상징은 추상적인 생각이나 정서를 구체적인 사물로 암시하는 방법이에요. 비유와 달리 원관념이 겉으로 드러나지 않고 보조 관념만 제시돼요. 널리 공유되는 관습적 상징과 작품 안에서만 의미를 가지는 개인적(창조적) 상징이 있어요.\n예: 비둘기 – 평화(관습적 상징) / 윤동주 '십자가'의 십자가 – 희생"),
        ce(.middle, "비유와 상징", ["반어법", "반어"], "반어법은 겉으로 표현한 말과 속뜻을 반대로 하여 의미를 강조하는 방법이에요. 상황의 아이러니를 통해 효과를 주기도 해요.\n예: 시험을 망친 친구에게 '참 잘했다.' / 김소월 '진달래꽃'의 '죽어도 아니 눈물 흘리우리다'"),
        ce(.middle, "비유와 상징", ["역설법", "역설"], "역설법은 겉으로는 앞뒤가 맞지 않고 모순된 것처럼 보이지만, 그 속에 깊은 진리나 의미를 담는 표현 방법이에요. 반어가 말과 속뜻의 차이라면, 역설은 표현 자체에 모순이 들어 있어요.\n예: '아아, 님은 갔지마는 나는 님을 보내지 아니하였습니다.' (한용운 '님의 침묵') / 찬란한 슬픔의 봄 (김영랑)"),
        ce(.middle, "비유와 상징", ["설의법", "대구법", "영탄법"], "설의법은 누구나 아는 내용을 의문문으로 던져 독자가 스스로 판단하게 하는 강조법이에요. 대구법은 비슷한 짜임의 구절을 짝지어 늘어놓는 방법이고, 영탄법은 감탄사나 감탄형 어미로 감정을 드러내는 방법이에요.\n예: 어찌 잊을 수 있으랴? (설의법) / 산은 높고 물은 깊다. (대구법) / 아아, 늬는 산새처럼 날아갔구나! (영탄법)"),

        ce(.middle, "소설의 구성", ["소설의 구성 단계", "발단 전개 위기 절정 결말"], "소설의 사건은 보통 발단 – 전개 – 위기 – 절정 – 결말의 다섯 단계로 짜여요. 발단에서는 인물과 배경이 소개되고, 전개에서 갈등이 생기며, 위기에서 갈등이 깊어지고, 절정에서 갈등이 최고조에 이른 뒤, 결말에서 해소돼요.\n예: '흥부전' – 발단(형제 소개) → 전개(쫓겨난 흥부) → 위기·절정(박을 탐) → 결말(놀부가 뉘우침)"),
        ce(.middle, "소설의 구성", ["갈등", "내적 갈등", "외적 갈등"], "갈등은 인물이 겪는 대립과 충돌로, 소설의 사건을 이끌어 가는 힘이에요. 한 인물의 마음속에서 일어나는 내적 갈등과, 인물과 인물·사회·운명·자연 사이에서 일어나는 외적 갈등이 있어요.\n예: 거짓말을 고백할지 망설이는 마음(내적 갈등) / 신분 차별에 맞서는 인물(인물과 사회의 갈등)"),

        ce(.middle, "설명 방법", ["정의", "정의하기"], "정의는 어떤 대상이나 용어의 뜻을 분명하게 밝혀 설명하는 방법이에요. 보통 'A는 B이다'의 형식으로, 종차(다른 것과 구별되는 특성)와 상위 개념을 함께 밝혀요.\n예: 시는 인간의 정서를 운율이 있는 언어로 압축하여 표현한 문학이다."),
        ce(.middle, "설명 방법", ["예시", "예시하기"], "예시는 구체적인 예를 들어 설명하는 방법이에요. 추상적이거나 낯선 내용을 독자가 쉽게 이해하도록 도와요.\n예: 우리나라에는 전통 놀이가 많다. 윷놀이, 제기차기, 연날리기 등이 대표적이다."),
        ce(.middle, "설명 방법", ["비교", "비교하기"], "비교는 둘 이상의 대상 사이의 공통점을 중심으로 설명하는 방법이에요. 차이점을 중심으로 설명하는 대조와 짝을 이루어 함께 쓰이는 경우가 많아요.\n예: 고래와 사람은 둘 다 폐로 숨을 쉬고 새끼를 젖을 먹여 기르는 포유류이다."),
        ce(.middle, "설명 방법", ["대조", "대조하기"], "대조는 둘 이상의 대상 사이의 차이점을 중심으로 설명하는 방법이에요. 두 대상의 특징을 뚜렷하게 드러낼 수 있어요.\n예: 동양화는 여백을 중시하는 반면, 서양화는 화면을 빈틈없이 채우는 경우가 많다."),
        ce(.middle, "설명 방법", ["분류", "구분", "분류와 구분"], "분류는 하위 항목들을 공통된 기준에 따라 상위 항목으로 묶어 설명하는 방법이고, 구분은 상위 항목을 기준에 따라 하위 항목으로 나누어 설명하는 방법이에요. 둘 다 일정한 기준이 있어야 해요.\n예: 참새, 독수리, 펭귄은 조류로 묶인다(분류). / 문학은 시, 소설, 수필, 희곡으로 나뉜다(구분)."),
        ce(.middle, "설명 방법", ["분석", "분석하기"], "분석은 하나의 대상을 구성 요소나 부분으로 나누어 설명하는 방법이에요. 대상 자체를 쪼개는 것이어서, 여러 대상을 종류별로 나누는 구분과 달라요.\n예: 꽃은 꽃잎, 꽃받침, 암술, 수술로 이루어져 있다."),
